// var leaks out of blocks -- a classic source of bugs
if (true) {
  var leaked = "I'm visible outside the if-block!";
}
console.log(leaked);   // works -- var ignores block boundaries

if (true) {
  let scoped = "I'm only visible inside the if-block";
}
try {
  console.log(scoped);   // ReferenceError -- let respects block boundaries
} catch (e) {
  console.log("Error:", e.message);
}

const x = 5;
try {
  x = 10;               // TypeError -- const cannot be reassigned
} catch (e) {
  console.log("Error:", e.message);
}

const arr = [1, 2, 3];
arr.push(4);            // this is FINE -- const prevents REASSIGNING the variable,
console.log(arr);        // not mutating the object/array it points to

function makeCounter() {
  let count = 0;             // 'count' lives in the closure's backpack
  return function () {
    count += 1;
    return count;
  };
}

const counter1 = makeCounter();
console.log(counter1());   // 1
console.log(counter1());   // 2
console.log(counter1());   // 3

const counter2 = makeCounter();   // a completely separate closure/backpack
console.log(counter2());   // 1 -- starts fresh, independent of counter1

// Arrow functions -- a shorter function syntax, commonly used in modern JS
const square = (x) => x * x;
const add = (a, b) => a + b;

console.log(square(5));     // 25
console.log(add(3, 4));      // 7

// Arrow functions are especially common as short callbacks
const nums = [1, 2, 3, 4];
const doubled = nums.map((n) => n * 2);
console.log(doubled);        // [2, 4, 6, 8]

const prices = [10, 25, 8, 42, 15];

const withTax = prices.map((p) => p * 1.08);       // same length, each transformed
console.log(withTax.map((p) => Math.round(p * 100) / 100));

const expensive = prices.filter((p) => p > 15);     // shorter, only matches kept
console.log(expensive);

const total = prices.reduce((sum, p) => sum + p, 0);   // one final value
console.log(total);

// Chaining: filter then map reads like a clear pipeline
const products = [
  { name: "Widget", price: 20, inStock: true },
  { name: "Gadget", price: 45, inStock: false },
  { name: "Gizmo", price: 15, inStock: true },
];

const availableNames = products
  .filter((p) => p.inStock)
  .map((p) => p.name);

console.log(availableNames);   // ['Widget', 'Gizmo']

function delay(ms, value) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(value), ms);
  });
}

async function main() {
  console.log("starting...");
  const result = await delay(100, "done!");   // pauses HERE, not the whole program
  console.log(result);
}

main();
console.log("this logs BEFORE 'done!' -- main() didn't block the rest of the program");

async function fetchUserSafely(id) {
  try {
    const user = await delay(50, { id, name: `user-${id}` });
    console.log("got:", user);
    return user;
  } catch (error) {
    console.log("failed:", error.message);
    return null;
  }
}

fetchUserSafely(42);

