// (Illustrative JSX -- matches React's own official Counter example exactly)
import { useState } from "react";

function Counter() {
  const [count, setCount] = useState(0);

  return (
    <>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </>
  );
}

// The underlying closure idea (Module 1, lesson 2) -- why state 'sticks' between calls
function makeStateHolder(initial) {
  let value = initial;
  const get = () => value;
  const set = (newValue) => { value = newValue; };
  return [get, set];
}

const [getCount, setCount] = makeStateHolder(0);
console.log(getCount());   // 0
setCount(getCount() + 1);
setCount(getCount() + 1);
console.log(getCount());   // 2 -- the closure 'remembers' value between calls

// (Illustrative JSX -- matches React's own official docs pattern)
function PeopleList({ people }) {
  return (
    <ul>
      {people.map((person) => (
        <li key={person.id}>{person.name}</li>    // GOOD: stable, unique id
      ))}
    </ul>
  );
}

// BAD (per React's own docs -- avoid this when the list can reorder):
// {people.map((person, index) => <li key={index}>{person.name}</li>)}

// Simulating WHY index-as-key breaks on reorder/deletion (plain JS logic, runnable now)
let peopleV1 = [{ id: 1, name: "Amy" }, { id: 2, name: "Bo" }, { id: 3, name: "Cy" }];
let peopleV2 = [{ id: 2, name: "Bo" }, { id: 3, name: "Cy" }];   // Amy (id 1) was deleted

console.log("--- using index as key ---");
peopleV1.forEach((p, i) => console.log(`key=${i} -> ${p.name}`));
peopleV2.forEach((p, i) => console.log(`key=${i} -> ${p.name}`));
// notice: Bo's key CHANGES from 1 to 0 -- React would think Bo's item was REPLACED, not just shifted

console.log("--- using id as key ---");
peopleV1.forEach((p) => console.log(`key=${p.id} -> ${p.name}`));
peopleV2.forEach((p) => console.log(`key=${p.id} -> ${p.name}`));
// notice: Bo's key stays 2 in both -- React correctly recognizes it as the SAME item

// (Illustrative JSX -- a controlled text input, standard React pattern)
import { useState } from "react";

function NameForm() {
  const [name, setName] = useState("");

  function handleSubmit(e) {
    e.preventDefault();          // stop the browser's default full-page-reload form submit
    console.log("Submitted:", name);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input
        value={name}                              // state drives what's shown -- controlled
        onChange={(e) => setName(e.target.value)}   // every keystroke updates state
      />
      <button type="submit">Submit</button>
    </form>
  );
}

// The underlying event-handler pattern is the same closure idea from Module 1's addEventListener
function simulateControlledInput() {
  let currentValue = "";              // stands in for React state
  const handleChange = (typedChar) => {
    currentValue += typedChar;         // simulating each keystroke updating state
    console.log("input now shows:", currentValue);
  };

  for (const char of "Hi") {
    handleChange(char);
  }
}
simulateControlledInput();

const express = require("express");
const app = express();
app.use(express.json());        // parses JSON request bodies automatically

app.get("/api/health", (req, res) => {
  res.json({ status: "ok" });
});

app.get("/api/users/:id", (req, res) => {     // :id is a URL parameter
  res.json({ id: req.params.id, name: `User ${req.params.id}` });
});

const server = app.listen(3999, () => console.log("server running"));

// Real requests against the running server (using Node's built-in fetch)
(async () => {
  const health = await fetch("http://localhost:3999/api/health");
  console.log(await health.json());

  const user = await fetch("http://localhost:3999/api/users/42");
  console.log(await user.json());

  server.close();
})();

const express2 = require("express");
const app2 = express2();
app2.use(express2.json());

app2.post("/api/echo", (req, res) => {
  res.json({ youSent: req.body });    // req.body is the parsed JSON from the request
});

const server2 = app2.listen(4000, () => console.log("server2 running"));

(async () => {
  const response = await fetch("http://localhost:4000/api/echo", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message: "hello from the client" }),
  });
  console.log(await response.json());
  server2.close();
})();

// Frontend-side fetch call (this is what a React component would do in an effect/handler)
async function getUsers() {
  const response = await fetch("http://localhost:4001/api/users");
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json();
}

// (Illustrative usage inside a React component. useEffect is a React hook that runs
// code after the component renders -- the empty [] means "run once, when the
// component first mounts." Here it calls getUsers() once and hands the result to
// the setUsers state setter from Module 2's useState lesson, so the component
// re-renders with the fetched data.)
